import sys

data = sys.stdin.read().split()
r, c, sr, sc = int(data[0]), int(data[1]), int(data[2]), int(data[3])
g = data[4:4 + r]
D = ((1, 0), (-1, 0), (0, 1), (0, -1))
isl = {(sr, sc)}
changed = True
while changed:
    changed = False
    for y in range(r):
        for x in range(c):
            if g[y][x] == 'X' and (y, x) not in isl:
                for dy, dx in D:
                    if (y + dy, x + dx) in isl:
                        isl.add((y, x))
                        changed = True
                        break


def reaches_border(y, x):
    seen = {(y, x)}
    q = [(y, x)]
    while q:
        a, b = q.pop()
        if a == 0 or b == 0 or a == r - 1 or b == c - 1:
            return True
        for dy, dx in D:
            nb = (a + dy, b + dx)
            if nb not in isl and nb not in seen:
                seen.add(nb)
                q.append(nb)
    return False


enclosed = set()
for y in range(r):
    for x in range(c):
        if (y, x) not in isl and not reaches_border(y, x):
            enclosed.add((y, x))
label = {}
lakes = 0
for cell in sorted(enclosed):
    if cell in label:
        continue
    lakes += 1
    label[cell] = lakes
    q = [cell]
    while q:
        a, b = q.pop()
        for dy, dx in D:
            nb = (a + dy, b + dx)
            if nb in enclosed and nb not in label:
                label[nb] = lakes
                q.append(nb)
print(len(isl), lakes)

